export function HomeScene() {
  const dismiss = Navigation.useDismiss()
  const [account, setAccount] = useState(getAccountStatus())
  const [keyword, setKeyword] = useState("")
  const [items, setItems] = useState<GallerySummary[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const requestEpoch = useRef(0)
  const loadHome = async () => { const epoch = ++requestEpoch.current; setLoading(true); setError(""); try { const page = await searchGalleries("", getBaseUrl()); if (epoch === requestEpoch.current) setItems(page.items) } catch (caught) { if (epoch === requestEpoch.current) setError(caught instanceof Error ? caught.message : String(caught)) } finally { if (epoch === requestEpoch.current) setLoading(false) } }
  useEffect(() => { void loadHome(); void ensureTagTranslations(); return () => { requestEpoch.current += 1 } }, [])
  const searchState = createHomeSearchState(keyword)
  return <List navigationTitle={account.site === "ex" ? "ExHentai" : "E-Hentai"} navigationBarTitleDisplayMode="inline" refreshable={loadHome} toolbar={{ cancellationAction: <Button title="关闭" action={dismiss} /> }} overlay={loading && !items.length ? <ProgressView title="正在加载画廊…" progressViewStyle="circular" /> : undefined} background={<PageBackground/>}>
    <Section header={<Text textCase={null}>搜索</Text>}><GlassSurface><TextField title="搜索画廊" value={keyword} onChanged={setKeyword} prompt="标题、作者、标签…" submitLabel="search" /></GlassSurface><NavigationLink destination={<ResultsView initial={searchState}/>}><Text>搜索</Text></NavigationLink><NavigationLink destination={<HomeFilterEntry initial={searchState}/>}><Text>筛选</Text></NavigationLink></Section>
    <Section header={<Text textCase={null}>发现</Text>}><NavigationLink destination={<ResultsView initial={createPopularSearchState()} />}><Text>热门画廊</Text></NavigationLink><NavigationLink destination={<ImageSearchScene/>}><Text>图片搜索</Text></NavigationLink><NavigationLink destination={<DiscoveryScene />}><Text>订阅更新与排行榜</Text></NavigationLink></Section>
    <Section header={<Text textCase={null}>我的内容</Text>}><NavigationLink destination={<LibraryScene />}><Text>书库</Text></NavigationLink><NavigationLink destination={<AccountScene onAccountChanged={status=>{setAccount(status);void loadHome()}}/>}><Text>{account.loggedIn ? "账号与设置" : "登录与设置"}</Text></NavigationLink></Section>
    <Section header={<Text textCase={null}>分类</Text>}><LazyVGrid columns={[{size:{type:"adaptive",min:96,max:180}}]} alignment="leading" spacing={10}>{GALLERY_CATEGORIES.slice(1).map(item => <NavigationLink key={item.key} destination={<ResultsView initial={createHomeSearchState("", item.key, "none")} />}><Text>{item.shortLabel}</Text></NavigationLink>)}</LazyVGrid></Section>
    <Section header={<Text textCase={null}>最新画廊</Text>}>{error?<ErrorText message={error}/>:null}{error ? <Button title="重试加载" buttonStyle="bordered" action={() => { void loadHome() }} /> : null}{!loading && !error && items.length === 0 ? <EmptyState message="暂时没有可显示的画廊，稍后下拉刷新或重试。" /> : null}{items.map(item => <NavigationLink key={item.id} destination={<GalleryDetailView summary={item} />}><GalleryRow item={item} /></NavigationLink>)}</Section>
    <Section header={<Text textCase={null}>外部</Text>} footer={<Text>将在系统浏览器中打开。</Text>}><VStack alignment="leading" spacing={9}><Button title="新闻" action={()=>void openExternalDestination("news").catch(setError)}/><Button title="论坛" action={()=>void openExternalDestination("forums").catch(setError)}/><Button title="Wiki" action={()=>void openExternalDestination("wiki").catch(setError)}/><Button title="种子" action={()=>void openExternalDestination("torrents").catch(setError)}/></VStack></Section>
  </List>
}

